  /* `--tv-border-disabled` resolves to `--tv-neutral-muted`, lifted above for MUTED
     TEXT — but the site also spends it on react-select's DISABLED border, which would
     then outshine the enabled one. */
  .react-select__control--is-disabled { border-color: #3f4854 !important; }
  /* The dropdown-surface rule above and the skeleton rule below both match
     react-select's inner parts by name and plate the control's own face. The
     `.react-select__control` ancestor is load-bearing: the skeleton rule is a single
     attribute selector further down, so a bare class would tie and lose on order.
     `react-select__input` is a 3px sizing input over the placeholder's first glyph,
     which the blanket `input` fill would clip. */
  .react-select__control .react-select__placeholder,
  .react-select__control .react-select__indicator,
